#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int a[1000];
    for (int i = 0; i < n; i++) if (scanf("%d", &a[i]) != 1) return 1;
    int x;
    if (scanf("%d", &x) != 1) return 1;

    int lo = 0, hi = n - 1, ket_qua = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) { ket_qua = mid; break; }
        if (a[mid] < x) lo = mid + 1;
        else hi = mid - 1;
    }
    printf("%d\n", ket_qua);
    return 0;
}
